/**
 * Zones where the river's pollution is documented to affect people's health, and the schools inside them.
 * Static layers in `public/data/`, generated by `scripts/build_health_layers.py` (INEGI DENUE + `scripts/zonas_salud.json`).
 */

export type Exposure =
  | 'aire_h2s_cov'
  | 'pozos_agua_potable'
  | 'riego_cultivos'
  | 'descargas_colorantes'
  | 'inundacion_lodos'
  | 'olores_estancamiento'
  | 'fauna_nociva_vectores'
  | 'metales_pesados_lirio';

/** `documentada`: health effects backed by the cited sources; `parcial`: some effects are only reported by residents. */
export type EvidenceLevel = 'documentada' | 'parcial';

export interface HealthSource {
  titulo: string;
  url: string;
  anio?: number;
}

export interface HealthZone {
  id: string;
  orden: number;
  nombre: string;
  estado: string;
  municipios: string[];
  comunidades: string[];
  nivel: 'critico' | 'atencion';
  evidencia: EvidenceLevel;
  exposiciones: Exposure[];
  efectos_salud: string[];
  descripcion: string;
  fuentes: HealthSource[];
  num_escuelas: number;
  trazo: 'aproximado';
  /** `[lng, lat]` of the zone's label point (always inside the polygon). */
  center?: [number, number];
}

export interface School {
  id: string;
  nombre: string;
  nivel: string;
  sostenimiento: 'Público' | 'Privado';
  municipio: string;
  localidad: string;
  zona_id: string;
  /** `[lng, lat]` */
  coordinates: [number, number];
}

/** Minimal GeoJSON shapes of the two files (only what the app reads). */
export interface HealthZonesGeoJson {
  type: 'FeatureCollection';
  features: {
    type: 'Feature';
    properties: ({ tipo: 'zona' } & HealthZone) | { tipo: 'etiqueta'; id: string; nombre: string; nivel: string };
    geometry: { type: string; coordinates: unknown };
  }[];
}

export interface SchoolsGeoJson {
  type: 'FeatureCollection';
  features: { type: 'Feature'; properties: Omit<School, 'coordinates'>; geometry: { type: 'Point'; coordinates: [number, number] } }[];
}
